CREATE TABLE recognition_state(id INTEGER PRIMARY KEY CHECK(id=1),active_version TEXT NOT NULL REFERENCES recognition_versions(id),catalog_revision INTEGER NOT NULL DEFAULT 0);
INSERT INTO recognition_state VALUES(1,'seed-v1',0);
CREATE TABLE recognition_previews(token TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES recognition_versions(id),active_version TEXT NOT NULL,catalog_revision INTEGER NOT NULL,ids_json TEXT NOT NULL,actor TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE recognition_guards(token TEXT PRIMARY KEY,valid INTEGER NOT NULL CHECK(valid=1));
CREATE TABLE recognition_applications(product_id TEXT PRIMARY KEY REFERENCES products(id),version_id TEXT NOT NULL REFERENCES recognition_versions(id),evidence_json TEXT NOT NULL,actor TEXT NOT NULL,applied_at TEXT NOT NULL);
CREATE TRIGGER recognition_products_insert AFTER INSERT ON products BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
CREATE TRIGGER recognition_products_update AFTER UPDATE ON products BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
CREATE TRIGGER recognition_products_delete AFTER DELETE ON products BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
CREATE TRIGGER recognition_suppliers_insert AFTER INSERT ON suppliers BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
CREATE TRIGGER recognition_suppliers_update AFTER UPDATE ON suppliers BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
CREATE TRIGGER recognition_suppliers_delete AFTER DELETE ON suppliers BEGIN UPDATE recognition_state SET catalog_revision=catalog_revision+1 WHERE id=1; END;
